-- Cấu hình trường kết quả riêng cho từng dịch vụ CLS.
-- Khoảng tham chiếu chỉ là ví dụ theo thông lệ; cơ sở phải hiệu chỉnh
-- theo máy, hóa chất, quy trình và giới hạn tham chiếu của labo.

UPDATE dich_vu_xet_nghiem
SET cau_hinh_ket_qua = CASE ma_dich_vu
  WHEN 'XN001' THEN '[{"key":"WBC","label":"Bạch cầu WBC","type":"number","unit":"G/L","reference":"4.0-10.0","section":"Huyết học"},{"key":"NEU_percent","label":"Bạch cầu trung tính NEU%","type":"number","unit":"%","reference":"40-75","section":"Huyết học"},{"key":"LYM_percent","label":"Lympho LYM%","type":"number","unit":"%","reference":"20-45","section":"Huyết học"},{"key":"MONO_percent","label":"Mono MONO%","type":"number","unit":"%","reference":"2-10","section":"Huyết học"},{"key":"EOS_percent","label":"Eosinophil EOS%","type":"number","unit":"%","reference":"0-6","section":"Huyết học"},{"key":"BASO_percent","label":"Basophil BASO%","type":"number","unit":"%","reference":"0-2","section":"Huyết học"},{"key":"RBC","label":"Hồng cầu RBC","type":"number","unit":"T/L","reference":"Nam 4.5-5.9; Nữ 4.0-5.2","section":"Hồng cầu"},{"key":"HGB","label":"Hemoglobin HGB","type":"number","unit":"g/dL","reference":"Nam 13-17; Nữ 12-16","section":"Hồng cầu"},{"key":"HCT","label":"Hematocrit HCT","type":"number","unit":"L/L","reference":"Nam 0.40-0.50; Nữ 0.35-0.47","section":"Hồng cầu"},{"key":"MCV","label":"Thể tích trung bình hồng cầu MCV","type":"number","unit":"fL","reference":"80-100","section":"Hồng cầu"},{"key":"MCH","label":"Lượng Hb trung bình hồng cầu MCH","type":"number","unit":"pg","reference":"27-33","section":"Hồng cầu"},{"key":"MCHC","label":"Nồng độ Hb trung bình MCHC","type":"number","unit":"g/dL","reference":"32-36","section":"Hồng cầu"},{"key":"RDW_CV","label":"Độ phân bố kích thước hồng cầu RDW-CV","type":"number","unit":"%","reference":"11.5-14.5","section":"Hồng cầu"},{"key":"PLT","label":"Tiểu cầu PLT","type":"number","unit":"G/L","reference":"150-450","section":"Tiểu cầu"},{"key":"MPV","label":"Thể tích trung bình tiểu cầu MPV","type":"number","unit":"fL","reference":"7-12","section":"Tiểu cầu"}]'
  WHEN 'XN002' THEN '[{"key":"Glucose","label":"Glucose máu lúc đói","type":"number","unit":"mmol/L","reference":"3.9-5.5 lúc đói","section":"Đường huyết"},{"key":"Urea","label":"Ure","type":"number","unit":"mmol/L","reference":"2.5-7.5","section":"Chức năng thận"},{"key":"Creatinine","label":"Creatinine","type":"number","unit":"µmol/L","reference":"Nam 62-115; Nữ 44-97","section":"Chức năng thận"},{"key":"AST","label":"Aspartate aminotransferase AST","type":"number","unit":"U/L","reference":"Nam <40; Nữ <35","section":"Men gan"},{"key":"ALT","label":"Alanine aminotransferase ALT","type":"number","unit":"U/L","reference":"Nam <41; Nữ <35","section":"Men gan"},{"key":"Bilirubin_total","label":"Bilirubin toàn phần","type":"number","unit":"µmol/L","reference":"5-21","section":"Chức năng gan-mật"},{"key":"Bilirubin_direct","label":"Bilirubin trực tiếp","type":"number","unit":"µmol/L","reference":"<5","section":"Chức năng gan-mật"},{"key":"Total_protein","label":"Protein toàn phần","type":"number","unit":"g/L","reference":"64-83","section":"Chức năng gan-mật"},{"key":"Albumin","label":"Albumin","type":"number","unit":"g/L","reference":"35-50","section":"Chức năng gan-mật"}]'
  WHEN 'XN003' THEN '[{"key":"Rate","label":"Tần số tim","type":"number","unit":"lần/phút","reference":"60-100","section":"Thông số đo"},{"key":"Rhythm","label":"Nhịp","type":"select","options":["Nhịp xoang","Rung nhĩ","Cuồng nhĩ","Nhịp nhanh trên thất","Khác"],"reference":"Ghi theo bản đọc ECG","section":"Phân tích nhịp"},{"key":"PR","label":"Khoảng PR","type":"number","unit":"ms","reference":"120-200","section":"Khoảng thời gian"},{"key":"QRS","label":"Thời gian QRS","type":"number","unit":"ms","reference":"<120","section":"Khoảng thời gian"},{"key":"QTc","label":"QT hiệu chỉnh QTc","type":"number","unit":"ms","reference":"Theo giới tính và máy đọc","section":"Khoảng thời gian"},{"key":"Axis","label":"Trục QRS","type":"text","unit":"độ","reference":"Khoảng -30 đến +90 thường gặp","section":"Điện học"},{"key":"ST_T","label":"Đoạn ST và sóng T","type":"textarea","reference":"Mô tả biến đổi nếu có","section":"Điện học"},{"key":"Conclusion","label":"Kết luận điện tâm đồ","type":"textarea","reference":"Bác sĩ/nhân viên chuyên môn kết luận","section":"Kết luận"}]'
  WHEN 'XN004' THEN '[{"key":"Color","label":"Màu sắc","type":"select","options":["Vàng nhạt","Vàng","Vàng đậm","Đỏ/nâu","Khác"],"reference":"Vàng nhạt","section":"Vật lý"},{"key":"Appearance","label":"Độ trong","type":"select","options":["Trong","Hơi đục","Đục"],"reference":"Trong","section":"Vật lý"},{"key":"Specific_gravity","label":"Tỷ trọng","type":"number","unit":"","reference":"1.005-1.030","section":"Hóa học"},{"key":"pH","label":"pH","type":"number","unit":"","reference":"5.0-8.0","section":"Hóa học"},{"key":"Protein","label":"Protein","type":"select","options":["Âm tính","Vết","1+","2+","3+","4+"],"reference":"Âm tính","section":"Hóa học"},{"key":"Glucose","label":"Glucose","type":"select","options":["Âm tính","Vết","1+","2+","3+","4+"],"reference":"Âm tính","section":"Hóa học"},{"key":"Ketone","label":"Ketone","type":"select","options":["Âm tính","Vết","1+","2+","3+","4+"],"reference":"Âm tính","section":"Hóa học"},{"key":"Bilirubin","label":"Bilirubin","type":"select","options":["Âm tính","Dương tính"],"reference":"Âm tính","section":"Hóa học"},{"key":"Urobilinogen","label":"Urobilinogen","type":"text","unit":"mg/dL","reference":"0.2-1.0","section":"Hóa học"},{"key":"Blood","label":"Hồng cầu/hemoglobin","type":"select","options":["Âm tính","Vết","1+","2+","3+"],"reference":"Âm tính","section":"Hóa học"},{"key":"Nitrite","label":"Nitrite","type":"select","options":["Âm tính","Dương tính"],"reference":"Âm tính","section":"Hóa học"},{"key":"Leukocyte_esterase","label":"Esterase bạch cầu","type":"select","options":["Âm tính","Vết","1+","2+","3+"],"reference":"Âm tính","section":"Hóa học"},{"key":"RBC_microscopy","label":"Hồng cầu soi cặn","type":"text","unit":"TB/vi trường","reference":"0-2","section":"Soi cặn nước tiểu"},{"key":"WBC_microscopy","label":"Bạch cầu soi cặn","type":"text","unit":"TB/vi trường","reference":"0-5","section":"Soi cặn nước tiểu"},{"key":"Bacteria","label":"Vi khuẩn","type":"select","options":["Không thấy","Ít","Vừa","Nhiều"],"reference":"Không thấy","section":"Soi cặn nước tiểu"}]'
  WHEN 'CD001' THEN '[{"key":"Lungs","label":"Nhu mô hai phổi","type":"textarea","reference":"Mô tả tổn thương, đám mờ, nốt, xẹp phổi nếu có","section":"Phổi"},{"key":"Pleura","label":"Màng phổi và góc sườn hoành","type":"textarea","reference":"Không tràn khí/tràn dịch hoặc mô tả bất thường","section":"Phổi"},{"key":"Heart","label":"Tim","type":"textarea","reference":"Kích thước, chỉ số tim-ngực nếu đánh giá được","section":"Tim-trung thất"},{"key":"Mediastinum","label":"Trung thất/rốn phổi","type":"textarea","reference":"Mô tả hình ảnh","section":"Tim-trung thất"},{"key":"Bones_soft_tissue","label":"Xương và phần mềm","type":"textarea","reference":"Mô tả bất thường nếu có","section":"Khác"},{"key":"Conclusion","label":"Kết luận X-Quang ngực","type":"textarea","reference":"Kết luận chẩn đoán hình ảnh","section":"Kết luận"}]'
  WHEN 'CD002' THEN '[{"key":"Liver","label":"Gan","type":"textarea","reference":"Kích thước, nhu mô, bờ, khu trú","section":"Tạng đặc"},{"key":"Gallbladder","label":"Túi mật","type":"textarea","reference":"Kích thước, thành, sỏi/bùn, dịch quanh túi mật","section":"Đường mật"},{"key":"Bile_duct","label":"Đường mật","type":"textarea","reference":"Đường mật trong/ngoài gan, ống mật chủ","section":"Đường mật"},{"key":"Pancreas","label":"Tụy","type":"textarea","reference":"Kích thước, nhu mô, ống tụy","section":"Tạng đặc"},{"key":"Spleen","label":"Lách","type":"textarea","reference":"Kích thước, nhu mô, tổn thương khu trú","section":"Tạng đặc"},{"key":"Right_kidney","label":"Thận phải","type":"textarea","reference":"Kích thước, nhu mô, sỏi, ứ nước","section":"Thận-tiết niệu"},{"key":"Left_kidney","label":"Thận trái","type":"textarea","reference":"Kích thước, nhu mô, sỏi, ứ nước","section":"Thận-tiết niệu"},{"key":"Bladder","label":"Bàng quang","type":"textarea","reference":"Mức độ căng, thành, lòng bàng quang","section":"Thận-tiết niệu"},{"key":"Aorta","label":"Động mạch chủ bụng","type":"textarea","reference":"Đường kính, phình/tắc nếu có","section":"Mạch máu"},{"key":"Ascites","label":"Dịch ổ bụng","type":"textarea","reference":"Không dịch hoặc vị trí/lượng dịch","section":"Phúc mạc"},{"key":"Conclusion","label":"Kết luận siêu âm ổ bụng","type":"textarea","reference":"Kết luận chẩn đoán hình ảnh","section":"Kết luận"}]'
  ELSE cau_hinh_ket_qua
END;

UPDATE dich_vu_xet_nghiem
SET mo_ta = CASE ma_dich_vu
  WHEN 'XN001' THEN 'Công thức máu ngoại vi: WBC, công thức bạch cầu, RBC, HGB, HCT, chỉ số hồng cầu, PLT và MPV. Mẫu máu tĩnh mạch chống đông EDTA.'
  WHEN 'XN002' THEN 'Sinh hóa máu: đường huyết, chức năng thận, men gan và một số chỉ số gan-mật. Ghi rõ thời điểm nhịn đói nếu xét nghiệm glucose lúc đói.'
  WHEN 'XN003' THEN 'Điện tâm đồ 12 chuyển đạo: tần số, nhịp, khoảng PR, QRS, QTc, trục, ST-T và kết luận.'
  WHEN 'XN004' THEN 'Tổng phân tích nước tiểu: vật lý, hóa học và soi cặn. Mẫu nước tiểu giữa dòng, lấy vào lọ sạch theo hướng dẫn.'
  WHEN 'CD001' THEN 'X-Quang ngực thẳng: phổi, màng phổi, tim, trung thất, xương và phần mềm; kèm kết luận hình ảnh.'
  WHEN 'CD002' THEN 'Siêu âm ổ bụng tổng quát: gan, túi mật, đường mật, tụy, lách, thận, bàng quang, mạch máu, dịch ổ bụng và kết luận.'
  ELSE mo_ta
END;
